"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["64610"],{97300(e){e.exports=JSON.parse('{"id":"V4-057","slug":"special-drawing-rights","term":"Special Drawing Rights","also_known_as":[],"difficulty":"Advanced","definition":"Special Drawing Rights (SDRs) are an international reserve asset created by the International Monetary Fund and allocated to its member countries, whose value is based on a basket of major currencies.","explanation":["SDRs were created in 1969 to supplement countries\u2019 official reserves, at a time when gold and US dollars were the main reserve assets. They are not a currency used by the public. Instead, member countries can exchange SDRs among themselves for usable currencies when they need them.","The value of the SDR is based on a basket of five currencies: the US dollar, the euro, the Chinese renminbi, the Japanese yen and the British pound. The renminbi was added in 2016. The basket is reviewed periodically.","The IMF allocates SDRs to members in proportion to their quotas, its measure of each country\u2019s size in the IMF. In 2021, during the COVID-19 pandemic, the IMF made its largest allocation ever, worth around 650 billion US dollars, to support global liquidity.","For example, a country facing a shortage of foreign currency reserves could exchange some of its SDRs for US dollars or euros through the IMF. The SDR is also the IMF\u2019s unit of account, used to denominate its loans and some international agreements."],"note":"","total":1725,"prev":{"slug":"special-dividend","term":"Special Dividend"},"next":{"slug":"special-purpose-acquisition-company","term":"Special Purpose Acquisition Company (SPAC)"}}')}}]);